package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_stage9_market_consensus") public class MarketConsensusEvidenceEntity {@Id private UUID id;@Column(nullable=false,length=40) private String symbol;@Column(nullable=false,length=1000) private String sourcesCsv;private double medianPrice;private double divergencePct;private long clockSkewSeconds;@Column(nullable=false) private Instant createdAt;protected MarketConsensusEvidenceEntity(){}public MarketConsensusEvidenceEntity(UUID id,MarketConsensus c){this.id=id;this.symbol=c.snapshot().symbol();this.sourcesCsv=String.join(",",c.sources());this.medianPrice=c.medianPrice();this.divergencePct=c.maxPriceDivergencePct();this.clockSkewSeconds=c.clockSkewSeconds();this.createdAt=Instant.now();}public UUID getId(){return id;}public String getSymbol(){return symbol;}public String getSourcesCsv(){return sourcesCsv;}public double getMedianPrice(){return medianPrice;}public double getDivergencePct(){return divergencePct;}public long getClockSkewSeconds(){return clockSkewSeconds;}public Instant getCreatedAt(){return createdAt;}}
